export const HELP_GLOSSARY: Record<string, HelpGlossaryEntry[]> = {"en":[{"key":"appeal","term":"appeal","means":"Asking for a decision to be looked at again. For a class assessment, you can appeal once, within 14 days.","see":"results-and-appeals"},{"key":"attempt","term":"attempt","means":"One go at an assessment, from starting it to the teacher's decision. If you're asked to resubmit, you start a new attempt.","see":"hand-in-your-work"},{"key":"campus-drive","term":"campus drive","means":"A company's hiring round at a college. Students apply, some are shortlisted and interviewed, and some get an offer.","see":"campus-jobs-and-interviews"},{"key":"career-center","term":"career center","means":"Your school's career office. Its staff help with appointments, résumés, jobs and internships.","see":"appointments"},{"key":"caseload","term":"caseload","means":"The students a career counselor is assigned to look after.","see":"caseload"},{"key":"change-task","term":"change task","means":"For some coding assessments, one small, timed change you make to your own code before the viva. It shows you know your code well.","see":"change-task-student"},{"key":"credential","term":"credential","means":"A signed record of something you passed. It has its own page, so anyone you share it with can check it's real.","see":"credentials-and-passport"},{"key":"decision","term":"decision","means":"The teacher's result for a piece of work. The work passes, is sent back to be handed in again, or doesn't pass.","see":"results-and-appeals"},{"key":"document-review","term":"document review","means":"Sending your résumé, cover letter or another document to your career center, so a counselor can comment on it.","see":"document-review"},{"key":"evidence","term":"evidence","means":"Everything a teacher looks at before deciding, such as the work handed in and the viva. For coding work, it also shows the tests and how the code was written.","see":"review-the-evidence"},{"key":"lms","term":"LMS","means":"Your school's online course system, such as Canvas, Moodle or Blackboard. Edulexa can send grades to it.","see":"results-credentials-lms"},{"key":"mentoring","term":"mentoring","means":"Advice from someone with more experience, often a graduate of your school, over a few conversations. It's free.","see":"mentoring"},{"key":"resume-book","term":"résumé book","means":"A school's collection of student résumés that approved employers can look through. Students choose whether to be in it.","see":"resume-book"},{"key":"roster","term":"roster","means":"The list of students in a class, with their e-mail addresses. Students sign in with the e-mail address on the roster.","see":"classes-and-rosters"},{"key":"rubric","term":"rubric","means":"The list of what the work is judged on, with the points for each part. Students can see it before they start.","see":"rubric-and-viva"},{"key":"skill-passport","term":"skill passport","means":"A page with your checked skills and a link you can share, for example with employers. You control what it shows.","see":"credentials-and-passport"},{"key":"two-step-sign-in","term":"two-step sign-in","means":"Signing in with your password and also a code from an app on your phone. Staff accounts need it, because they can see students' information.","see":"sign-in"},{"key":"viva","term":"viva","means":"A short spoken conversation about your own work, where you explain what you did and why. Your teacher listens to it later.","see":"the-viva"},{"key":"voice-minutes","term":"voice minutes","means":"The time available for spoken conversations with the AI, such as voice vivas. When they run out, students answer in writing instead.","see":"billing-and-voice-minutes"},{"key":"wallet","term":"wallet","means":"The place in your account where your credentials are kept. You decide which ones to share.","see":"credentials-and-passport"}]};

